ALTER TABLE users ADD COLUMN last_seen INTEGER;
UPDATE users SET last_seen=created WHERE last_seen IS NULL;
CREATE TABLE IF NOT EXISTS activity(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,day INTEGER NOT NULL,PRIMARY KEY(user_id,day));
CREATE INDEX IF NOT EXISTS idx_activity_day ON activity(day);
CREATE TABLE IF NOT EXISTS feedback(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,ctx TEXT NOT NULL,note_app INTEGER NOT NULL CHECK(note_app BETWEEN 1 AND 5),note_cours INTEGER NOT NULL CHECK(note_cours BETWEEN 1 AND 5),note_eval INTEGER NOT NULL CHECK(note_eval BETWEEN 1 AND 5),reco INTEGER NOT NULL CHECK(reco BETWEEN 0 AND 10),comment TEXT,created INTEGER NOT NULL,UNIQUE(user_id,ctx));
CREATE INDEX IF NOT EXISTS idx_feedback_created ON feedback(created);
